"""matplotlib._pylab_helpers — figure-manager registry shim.

Upstream uses Gcf to track every open figure across the GUI backends.
The plotly backend has at most one active figure at a time (pyplot's
`_ensure_fig` returns the current one or creates it), so Gcf only needs
to expose `get_fig_manager`, `set_active`, `destroy`, and
`get_all_fig_managers` returning a single-entry list.
"""


class _Manager:
    """Stand-in for matplotlib's FigureManager — holds the figure
    reference plus a window title (which the plotly backend surfaces
    as the layout's ``title`` field if the user reads it back)."""

    def __init__(self, canvas=None, num=1):
        self.canvas = canvas
        self.num = num
        self._window_title = ''

    def show(self):
        """Show the underlying figure. Delegates to pyplot.show() so
        the in-app preview pane actually displays the chart."""
        try:
            from matplotlib import pyplot as _plt
            _plt.show()
        except Exception:
            pass

    def destroy(self):
        """Remove this manager from the global registry."""
        Gcf.destroy(self.num)

    def set_window_title(self, title):
        self._window_title = '' if title is None else str(title)

    def get_window_title(self):
        return self._window_title

    def resize(self, w, h):
        """Resize the underlying figure to (w, h) pixels."""
        if self.canvas is not None and hasattr(self.canvas, 'set_size_inches'):
            try:
                # Convert pixels → inches at default dpi=100.
                self.canvas.set_size_inches(w / 100.0, h / 100.0)
            except Exception:
                pass

    def full_screen_toggle(self): pass
    def get_size(self): return (800, 600)


class Gcf:
    figs: dict = {}  # type: ignore[var-annotated]

    @classmethod
    def get_fig_manager(cls, num=1):
        return cls.figs.get(num)

    @classmethod
    def destroy(cls, num=None):
        if num is None:
            cls.figs.clear()
        else:
            cls.figs.pop(num, None)

    @classmethod
    def destroy_fig(cls, fig):
        for k, m in list(cls.figs.items()):
            if getattr(m, 'canvas', None) is fig:
                cls.figs.pop(k, None)

    @classmethod
    def destroy_all(cls):
        cls.figs.clear()

    @classmethod
    def has_fignum(cls, num):
        return num in cls.figs

    @classmethod
    def get_all_fig_managers(cls):
        return list(cls.figs.values())

    @classmethod
    def get_num_fig_managers(cls):
        return len(cls.figs)

    @classmethod
    def get_active(cls):
        if not cls.figs: return None
        return next(reversed(cls.figs.values()))

    @classmethod
    def _set_new_active_manager(cls, manager):
        cls.figs[manager.num] = manager

    @classmethod
    def set_active(cls, manager):
        cls._set_new_active_manager(manager)

    @classmethod
    def draw_all(cls, force=False):
        pass
